export function getSiswaData() {
  const stored = localStorage.getItem(SISWA_STORAGE_KEY);
  if (stored) {
    try {
      return JSON.parse(stored);
    } catch (e) {
      console.error('Error parsing stored siswa data:', e);
    }
  }
  return INITIAL_SISWA_DATA;
}

export function saveSiswaItem(siswaObj) {
  const list = getSiswaData();
  const index = list.findIndex(s => s.id === siswaObj.id || (siswaObj.nisn && s.nisn === siswaObj.nisn));
  
  if (index >= 0) {
    list[index] = { ...list[index], ...siswaObj };
  } else {
    const nextId = `S-${String(list.length + 1).padStart(3, '0')}`;
    list.unshift({ id: nextId, status: 'Aktif', ...siswaObj });
  }

  localStorage.setItem(SISWA_STORAGE_KEY, JSON.stringify(list));
  return list;
}

export function deleteSiswaItem(id) {
  let list = getSiswaData();
  list = list.filter(s => s.id !== id);
  localStorage.setItem(SISWA_STORAGE_KEY, JSON.stringify(list));
  return list;
}

export function resetSiswaDatabase() {
  localStorage.removeItem(SISWA_STORAGE_KEY);
  return INITIAL_SISWA_DATA;
}

export const resetSiswaData = resetSiswaDatabase;

export function parseTingkat(kelasStr) {
  if (!kelasStr) return 'X';
  const clean = kelasStr.trim().toUpperCase();
  if (clean.startsWith('XII')) return 'XII';
  if (clean.startsWith('XI')) return 'XI';
  if (clean.startsWith('X')) return 'X';
  return 'X';
}

export function parseJurusan(kelasStr) {
  if (!kelasStr) return 'Umum';
  const clean = kelasStr.trim().toUpperCase();
  if (clean.includes('TKR')) return 'Teknik Kendaraan Ringan';
  if (clean.includes('TKJ')) return 'Teknik Komputer dan Jaringan';
  if (clean.includes('TAV')) return 'Teknik Audio Visual';
  return 'Umum';
}
